/* GOLDEN — Music Industry Life Sim, version 1. Slot-scoped local saves. */
(()=>{'use strict';
const KEY='golden-saves-v1',SETTINGS='golden-settings-v1';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n||0),compact=n=>new Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:1}).format(n||0),clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),pick=a=>a[Math.floor(Math.random()*a.length)],id=()=>Math.random().toString(36).slice(2,9);
const eras=[
{from:1970,to:1979,tag:'THE SOUL & DISCO ERA',genres:['Soul','Funk','Disco','Jazz','Gospel','Rock'],tech:'8-track tape · FM radio · vinyl',dist:'Vinyl & radio'},
{from:1980,to:1989,tag:'THE MTV & SYNTH ERA',genres:['R&B','Soul','New Jack Swing','Hip-Hop','Funk','Pop','Rock'],tech:'Cassette · drum machines · music video',dist:'Vinyl, cassette & video'},
{from:1990,to:1999,tag:'THE CD & HIP-HOP ERA',genres:['R&B','Hip-Hop','Rap','Neo-Soul','Pop','Rock','Jazz'],tech:'CD · samplers · home studios',dist:'CD, cassette & radio'},
{from:2000,to:2009,tag:'THE DIGITAL DOWNLOAD ERA',genres:['Contemporary R&B','Hip-Hop','Rap','Pop','Neo-Soul','Alternative R&B'],tech:'Pro Tools · MP3 · online stores',dist:'CD, downloads & ringtones'},
{from:2010,to:2019,tag:'THE STREAMING ERA',genres:['Contemporary R&B','Alternative R&B','Hip-Hop','Rap','Pop','Neo-Soul','Gospel'],tech:'DAWs · streaming · social media',dist:'Downloads & streaming'},
{from:2020,to:2029,tag:'THE CREATOR ECONOMY',genres:['Contemporary R&B','Alternative R&B','Hip-Hop','Rap','Pop','Neo-Soul','Jazz'],tech:'Remote studios · short-form video · AI tools',dist:'Streaming & direct-to-fan'},
{from:2030,to:9999,tag:'THE NEXT SOUND',genres:['Contemporary R&B','Alternative R&B','Hip-Hop','Rap','Pop','Neo-Soul'],tech:'Immersive audio · direct-to-fan',dist:'Global digital platforms'}];
const era=y=>eras.find(e=>y>=e.from&&y<=e.to)||eras[eras.length-1];
const famous=[['Stevie Wonder','Soul',1950,2020],['Marvin Gaye','Soul',1939,1984],['Aretha Franklin','Soul',1942,2018],['Donna Summer','Disco',1948,2012],['Diana Ross','Soul',1944,2026],['Prince','Funk',1958,2016],['Whitney Houston','R&B',1963,2012],['Janet Jackson','R&B',1966,2026],['Michael Jackson','Pop',1958,2009],['Tina Turner','Rock',1939,2023],['Bobby Brown','New Jack Swing',1969,2026],['Teddy Riley','New Jack Swing',1967,2026],['Mary J. Blige','R&B',1971,2026],['TLC','R&B',1970,2026],['Aaliyah','R&B',1979,2001],['Lauryn Hill','Hip-Hop',1975,2026],['Nas','Hip-Hop',1973,2026],['Jay-Z','Hip-Hop',1969,2026],['Missy Elliott','Hip-Hop',1971,2026],['Beyoncé','R&B',1981,2026],['Usher','R&B',1978,2026],['Alicia Keys','R&B',1981,2026],['Kanye West','Hip-Hop',1977,2026],['Rihanna','Pop',1988,2026],['Drake','Hip-Hop',1986,2026],['Frank Ocean','Alternative R&B',1987,2026],['SZA','R&B',1989,2026],['The Weeknd','R&B',1990,2026],['Kendrick Lamar','Hip-Hop',1987,2026],['Tyler, the Creator','Hip-Hop',1991,2026],['H.E.R.','R&B',1997,2026],['Victoria Monét','R&B',1989,2026]];
const firsts=['Jade','Marcus','Nova','Darius','Imani','Theo','Avery','Renee','Malik','Sage','Zion','Nia','Cruz','Ari','Milan','Amara','Kai','Raven','Andre','Skye','Jules','Khalil','Lena','Noel'];
const lasts=['Stone','Monroe','Banks','Carter','Reed','Wilder','James','Cole','Brooks','Saint','Mercer','Blue','Knight','Ellis','Cruz','West','Hayes','Rivers','Love','Young','Vale','Hart','Rhodes'];
const genres=['R&B','Soul','New Jack Swing','Hip-Hop','Rap','Funk','Disco','Pop','Neo-Soul','Contemporary R&B','Alternative R&B','Gospel','Rock','Jazz'];
const names=['Midnight Radio','Velvet Season','No Apologies','Side A','Afterglow','City of Gold','Slow Burn','Run It Back','Good Company','Open Doors','Blue Hour','All This Time','Sweet Talk','New Money','Homecoming','Summer Never Ends'];
let saves=loadSaves(),activeId=null,state=null,page='dashboard',styleTab='clothes',modal=null,toastTimer;
function loadSaves(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')}catch{return{}}}function save(){if(state&&activeId){saves[activeId]=state;localStorage.setItem(KEY,JSON.stringify(saves))}}function notify(t){const root=$('#toast-root');if(root){root.innerHTML=`<div class="toast">${esc(t)}</div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>root.innerHTML='',2600)}}
function makeArtist(year){let f=pick(firsts),l=pick(lasts),genre=pick(era(year).genres),age=18+Math.floor(Math.random()*24);return{id:id(),name:`${f} ${l}`,stage:`${f} ${l}`,age,genre,personality:pick(['ambitious','enigmatic','generous','restless','perfectionist','charismatic']),pop:8+Math.random()*38,heat:5+Math.random()*25,active:true,real:false,relations:{},releases:[],retired:false}}
function worldArtists(year){let list=famous.filter(a=>year>=a[2]&&year<=a[3]).map(a=>({id:'real-'+a[0].replace(/\W/g,''),name:a[0],stage:a[0],age:Math.max(18,year-a[2]),genre:a[1],personality:'iconic',pop:35+Math.random()*60,heat:25+Math.random()*60,active:true,real:true,relations:{},releases:[],retired:false}));while(list.length<30)list.push(makeArtist(year));return list}
function makeTrack(artist,title,genre,pop,kind='Single',releaseYear=0){return{id:id(),artistId:artist.id,artist:artist.stage||artist.name,title,genre,pop,score:Math.max(1,pop*1.3),streams:0,sales:0,kind,year:releaseYear,weeks:0,player:false}}
function createCareer(d,slot){let year=+d.year||1978;let c={id:slot,character:{first:d.first,last:d.last,stage:d.stage||`${d.first} ${d.last}`,birth:d.birth||`${year-18}-06-15`,location:d.location||'Detroit, Michigan',avatar:d.avatar||'🎙️',style:'Vintage Soul',tattoos:[],jewelry:[],wardrobe:['Everyday Look'],outfits:[]},year,week:1,ep:100,cash:25000,heat:4,popularity:2,careerStatus:'Independent artist',releases:[],tracks:[],artists:worldArtists(year),relationships:{},groups:[],label:null,contracts:[],garage:[],properties:[],investments:0,totalStreams:0,totalSales:0,royalties:0,awards:[],achievements:[],news:[],activities:[],chart:{hot:[],albums:[]},stats:{shows:0,collaborations:0,weeks:0,numberOnes:0},settings:{},lastReport:null};
for(let i=0;i<32;i++){let a=pick(c.artists),t=makeTrack(a,pick(names),a.genre,a.pop*pick([.35,.55,.72,1.1]),'Single',year);c.tracks.push(t)}
for(let i=0;i<5;i++){let a=makeArtist(year);c.artists.push(a)}
c.news=[{icon:'✦',text:`A new generation is finding its voice in ${esc(d.location||'the city')}. The industry is listening.`,when:`${year} · Week 1`}];return c}
function age(){let [y,m,day]=state.character.birth.split('-').map(Number);return Math.max(0,state.year-y-(state.week<Math.ceil((m*4+day/7)/52)?1:0))}function fmtDate(){return `${state.year} · WEEK ${String(state.week).padStart(2,'0')}`}function careerYears(){return state.year-(+state.character.birth.slice(0,4))}
const nav=[['dashboard','⌂','Dashboard'],['music','♫','Music'],['charts','▥','Charts'],['industry','◎','Industry'],['business','▣','Business'],['clothing','◇','Style'],['lifestyle','⌑','Lifestyle'],['character','☻','Character']];
function shell(content){let active=nav.find(x=>x[0]===page)||nav[0];return `<div class="app-shell"><aside class="sidebar"><div class="brand">G<span>•</span>LDEN<small>THE MUSIC LIFE SIM</small></div><nav class="side-nav"><div class="nav-label">YOUR CAREER</div>${nav.map(n=>`<button class="nav-btn ${page===n[0]?'active':''}" data-nav="${n[0]}"><span class="nav-icon">${n[1]}</span><span class="nav-text">${n[2]}</span></button>`).join('')}</nav><div class="side-bottom">${esc(fmtDate())}<br>INDEPENDENT SINCE DAY ONE</div></aside><main class="main"><header class="topbar"><div class="eyebrow">${esc(era(state.year).tag)}<br>${esc(era(state.year).tech)}</div><div class="top-actions"><span class="stat-pill">${esc(fmtDate())}</span><span class="stat-pill">EP <b>${state.ep}</b></span><button class="btn primary" data-action="next-week">NEXT WEEK ↗</button></div></header>${content}</main><nav class="mobile-bar">${nav.slice(0,5).map(n=>`<button class="${page===n[0]?'active':''}" data-nav="${n[0]}"><i>${n[1]}</i>${n[2]}</button>`).join('')}<button data-nav="lifestyle" class="${page==='lifestyle'?'active':''}"><i>⌑</i>Life</button><button data-nav="character" class="${page==='character'?'active':''}"><i>☻</i>Me</button></nav></div>${modal?renderModal():''}`}
function startScreen(){const slots=Object.values(saves);return `<div class="creation-screen"><div class="creation-card"><div class="creation-logo">G•LDEN — A MUSIC LIFE SIMULATOR</div><h1 class="creation-title">Make noise.<br>Make history.</h1><p class="creation-copy">Build a life in music, one week at a time. Make records, find your people, move the culture, and decide what your legacy sounds like.</p><div class="split" style="margin-bottom:18px"><span class="eyebrow">YOUR CAREERS</span><button class="btn primary" data-action="new-career">＋ Start a career</button></div>${slots.length?`<div class="slot-list">${slots.map(s=>`<div class="slot"><div class="slot-info"><b>${esc(s.character.stage)}</b><span>${esc(s.character.first+' '+s.character.last)} · ${s.year} · ${money(s.cash)} cash</span></div><div class="modal-buttons"><button class="btn small primary" data-load="${s.id}">Continue</button><button class="btn small danger" data-delete="${s.id}">Delete</button></div></div>`).join('')}</div>`:`<div class="empty">No careers yet. Your first chapter is waiting.</div>`}<p class="footer-note">LOCAL SAVES · ${slots.length}/5 CAREERS · V1.0</p></div></div>${modal?renderModal():''}`}
function render(){const root=$('#app');if(!state){root.innerHTML=startScreen();return}let content=({dashboard:dashboardPage,music:musicPage,charts:chartsPage,industry:industryPage,business:businessPage,clothing:clothingPage,lifestyle:lifestylePage,character:characterPage}[page]||dashboardPage)();root.innerHTML=shell(content)}
function metrics(){return `<div class="metric-grid"><div class="metric"><div class="metric-label">AGE · ${age()} YEARS</div><div class="metric-value">${esc(state.character.first)}</div><div class="metric-note">${esc(state.character.location)}</div></div><div class="metric"><div class="metric-label">HEAT</div><div class="metric-value">${Math.round(state.heat)}°</div><div class="bar"><i style="width:${clamp(state.heat,0,100)}%"></i></div></div><div class="metric"><div class="metric-label">POPULARITY</div><div class="metric-value">${Math.round(state.popularity)}</div><div class="metric-note">out of 100</div></div><div class="metric cash"><div class="metric-label">CASH</div><div class="metric-value">${money(state.cash)}</div><div class="metric-note">available balance</div></div><div class="metric"><div class="metric-label">NET WORTH</div><div class="metric-value">${money(netWorth())}</div><div class="metric-note">assets + cash</div></div></div>`}
function netWorth(){return state.cash+state.properties.reduce((s,p)=>s+p.value,0)+state.garage.reduce((s,c)=>s+c.value,0)+state.investments+Math.round(state.royalties*.15)}
function feed(items,limit=5){return items.slice(0,limit).map(n=>`<div class="feed-item"><div class="feed-icon">${n.icon||'♪'}</div><div><div class="feed-text">${esc(n.text)}</div><div class="feed-time">${esc(n.when||fmtDate())}</div></div></div>`).join('')||'<div class="empty">The industry is quiet. Make something happen.</div>'}
function releaseRows(list){return list.slice().reverse().slice(0,4).map(r=>`<div class="release-row"><div class="cover">♫</div><div class="row-main"><div class="row-title">${esc(r.title)}</div><div class="row-sub">${esc(r.kind)} · ${esc(r.genre)} · ${r.year}</div></div><div class="row-value">${compact(r.streams)}<br><span class="tiny">streams</span></div></div>`).join('')||'<div class="empty">No releases yet. Your studio is waiting.</div>'}
function dashboardPage(){let top=state.chart.hot.slice(0,3);return `<div class="hero"><div class="hero-content"><div class="avatar">${esc(state.character.avatar)}</div><div><div class="artist-handle">${esc(state.character.stage.toUpperCase())} · ${esc(state.careerStatus.toUpperCase())}</div><h1 class="hero-name">${esc(state.character.first)} ${esc(state.character.last)}</h1><div class="hero-meta"><span class="tag">${esc(state.character.location)}</span><span class="tag">${age()} YEARS OLD</span><span class="tag">${esc(state.character.style)}</span><span class="tag">${esc(era(state.year).dist)}</span></div><div class="hero-actions"><button class="btn primary" data-nav="music">＋ Make music</button><button class="btn" data-action="perform">♫ Play a show · 15 EP</button><button class="btn ghost" data-nav="character">Edit character ↗</button></div></div></div></div>${metrics()}<div class="columns"><div><section class="card"><div class="card-head"><div><div class="card-kicker">THE WORK</div><h2 class="card-title">Latest releases</h2></div><button class="btn small" data-nav="music">Discography ↗</button></div>${releaseRows(state.releases)}</section><section class="card"><div class="card-head"><div><div class="card-kicker">THE MOMENT</div><h2 class="card-title">Chart watch</h2></div><button class="btn small" data-nav="charts">Full charts ↗</button></div>${top.length?top.map((t,i)=>`<div class="list-row"><div class="rank">#${i+1}</div><div class="row-main"><div class="row-title">${esc(t.title)} <span class="tiny">— ${esc(t.artist)}</span></div><div class="row-sub">${esc(t.genre)} · ${compact(t.streams)} streams</div></div><div class="badge ${t.player?'':'gray'}">${t.player?'YOU':'HOT 100'}</div></div>`).join(''):'<div class="empty">Charts update after your first week.</div>'}</section><section class="card"><div class="card-head"><div><div class="card-kicker">YOUR NEXT MOVE</div><h2 class="card-title">Make this week count</h2></div><span class="badge">${state.ep} EP LEFT</span></div><div class="quick-grid"><button class="quick-card" data-nav="music"><span class="quick-icon">♫</span><b>Make a record</b><span>Start a new song, single, EP or album.</span></button><button class="quick-card" data-nav="industry"><span class="quick-icon">◎</span><b>Meet the scene</b><span>Build relationships or make a rival.</span></button><button class="quick-card" data-nav="business"><span class="quick-icon">▣</span><b>Build a label</b><span>Sign talent and grow your imprint.</span></button></div></section></div><div><section class="card"><div class="card-head"><div><div class="card-kicker">RIGHT NOW</div><h2 class="card-title">Industry feed</h2></div><span class="badge gray">${esc(fmtDate())}</span></div><div class="news-feed">${feed(state.news,7)}</div></section><section class="card"><div class="card-head"><div><div class="card-kicker">THE LONG GAME</div><h2 class="card-title">Career milestones</h2></div></div>${milestoneRows()}</section><section class="card"><div class="card-head"><div><div class="card-kicker">WEEKLY RHYTHM</div><h2 class="card-title">Energy</h2></div><span class="progress">${state.ep} / 100 EP</span></div><div class="bar"><i style="width:${state.ep}%"></i></div><p class="tiny">Your energy restores next week. Choose your moves; the music industry keeps moving without you.</p><button class="btn primary" style="width:100%" data-action="next-week">Advance one week ↗</button></section></div></div>`}
function milestoneRows(){let m=[['🎙','First release',state.releases.length>0],['♬','10,000 streams',state.totalStreams>=10000],['✦','Chart debut',state.chart.hot.some(t=>t.player)],['▣','Label founder',!!state.label],['◈','Millionaire',netWorth()>=1e6]];return m.map(x=>`<div class="achievement"><span class="medal">${x[0]}</span><div><b>${x[1]}</b><span>${x[2]?'Unlocked':'In progress'}</span></div><span class="badge ${x[2]?'':'gray'}" style="margin-left:auto">${x[2]?'DONE':'—'}</span></div>`).join('')}
function musicPage(){return `<h1 class="page-title">Make music.</h1><p class="page-subtitle">Create work, build a catalog, and turn your sound into a career. ${esc(era(state.year).tech)} is in the room.</p><div class="section-grid"><section class="card"><div class="card-head"><div><div class="card-kicker">CREATE</div><h2 class="card-title">Start something</h2></div><span class="badge">10 EP · SONG</span></div><p class="tiny">Your sound, your call. Releases build popularity and long-tail royalties; quality, promotion and collaborators all matter.</p><div class="choice-list"><button class="choice" data-action="create-release" data-kind="Single"><b>♫ Record a single</b><span>One focused track. 10 EP. Best for making a statement.</span></button><button class="choice" data-action="create-release" data-kind="EP"><b>▤ Build an EP</b><span>A short-form project. 25 EP and a bigger production budget.</span></button><button class="choice" data-action="create-release" data-kind="Album"><b>▦ Make an album</b><span>A full-length statement. 40 EP; greater reach and greater risk.</span></button><button class="choice" data-action="form-group"><b>♬ Form a group</b><span>Bring artists together around a shared sound.</span></button></div></section><section class="card"><div class="card-head"><div><div class="card-kicker">YOUR CATALOG</div><h2 class="card-title">Discography</h2></div><span class="badge gray">${state.releases.length} RELEASE${state.releases.length===1?'':'S'}</span></div>${releaseRows(state.releases)}${state.releases.length?`<div class="wealth-row"><span>Lifetime streams</span><span>${compact(state.totalStreams)}</span></div><div class="wealth-row"><span>Lifetime sales</span><span>${compact(state.totalSales)}</span></div><div class="wealth-row"><span>Royalties earned</span><span>${money(state.royalties)}</span></div>`:''}</section></div><section class="card"><div class="card-head"><div><div class="card-kicker">ROOM TO GROW</div><h2 class="card-title">Your creative team</h2></div><button class="btn small" data-nav="industry">Explore artists ↗</button></div><div class="list-row"><div class="cover">◉</div><div class="row-main"><div class="row-title">Collaborate with an artist</div><div class="row-sub">Find a feature, co-write, or make a connection.</div></div><button class="btn small" data-nav="industry">Browse</button></div><div class="list-row"><div class="cover">♫</div><div class="row-main"><div class="row-title">Invest in the recording</div><div class="row-sub">A larger production budget boosts quality and chart potential.</div></div><span class="badge gray">IN RELEASE FORM</span></div></section>`}
function chartsPage(){let hot=state.chart.hot,albums=state.chart.albums;return `<h1 class="page-title">The charts.</h1><p class="page-subtitle">A living snapshot of the industry's biggest records. Radio, sales, streaming, promotion and cultural momentum all move the needle.</p><div class="tabs"><button class="tab active" data-tab="hot">Hot 100</button><button class="tab" data-tab="albums">Billboard 200</button><button class="tab" data-tab="genre">Genre charts</button><button class="tab" data-tab="artists">Artist rankings</button></div><div id="chart-view">${chartTable(hot,'HOT 100')}</div><div class="section-grid"><section class="card"><div class="card-head"><div><div class="card-kicker">CAREER TRACKER</div><h2 class="card-title">Certifications</h2></div></div>${state.releases.length?state.releases.map(r=>`<div class="list-row"><div class="cover">♫</div><div class="row-main"><div class="row-title">${esc(r.title)}</div><div class="row-sub">${esc(r.genre)} · ${compact(r.streams)} streams</div></div><span class="badge ${r.cert?'':'gray'}">${esc(r.cert||'NOT CERTIFIED')}</span></div>`).join(''):'<div class="empty">Certifications start with your first release.</div>'}</section><section class="card"><div class="card-head"><div><div class="card-kicker">ON THE RISE</div><h2 class="card-title">Artist rankings</h2></div></div>${state.artists.slice().sort((a,b)=>b.pop-a.pop).slice(0,6).map((a,i)=>`<div class="list-row"><div class="rank">${String(i+1).padStart(2,'0')}</div><div class="row-main"><div class="row-title">${esc(a.stage)} ${a.real?'<span class="tiny">REAL ARTIST</span>':''}</div><div class="row-sub">${esc(a.genre)} · ${Math.round(a.pop)} popularity</div></div><div class="bar" style="width:65px"><i style="width:${a.pop}%"></i></div></div>`).join('')}</section></div>`}
function chartTable(list,title){if(!list?.length)return `<div class="empty">The ${title} will take shape after the next weekly chart update.</div>`;return `<div class="card" style="overflow:auto"><table class="table"><thead><tr><th>#</th><th>Title / Artist</th><th>Genre</th><th>Streams</th><th>Weeks</th><th>Peak</th></tr></thead><tbody>${list.slice(0,30).map((t,i)=>`<tr><td class="rank">${i+1}</td><td><b>${esc(t.title)}</b><div class="row-sub">${esc(t.artist)}${t.player?' · YOU':''}</div></td><td>${esc(t.genre)}</td><td>${compact(t.streams)}</td><td>${t.weeks||1}</td><td>${t.peak||i+1}</td></tr>`).join('')}</tbody></table></div>`}
function industryPage(){let ordered=state.artists.slice().sort((a,b)=>b.pop-a.pop),known=Object.entries(state.relationships);return `<h1 class="page-title">The industry.</h1><p class="page-subtitle">A scene full of ambition, friendships, creative chemistry and competition. People remember how you treat them.</p><div class="section-grid"><section class="card"><div class="card-head"><div><div class="card-kicker">THE SCENE</div><h2 class="card-title">Artists to know</h2></div><span class="badge gray">${state.artists.length} ACTIVE</span></div><div class="field"><input id="artist-search" placeholder="Search artists or genres…"></div><div id="artist-list">${artistRows(ordered.slice(0,12))}</div><button class="btn small" data-action="show-more-artists">Show more artists</button></section><section><section class="card"><div class="card-head"><div><div class="card-kicker">YOUR CIRCLE</div><h2 class="card-title">Relationships</h2></div></div>${known.length?known.map(([aid,r])=>{let a=state.artists.find(x=>x.id===aid);return a?`<div class="list-row"><div class="cover">◎</div><div class="row-main"><div class="row-title">${esc(a.stage)}</div><div class="row-sub">${esc(a.genre)} · ${r.type}</div></div><span class="badge">${r.score}</span></div>`:''}).join(''):'<div class="empty">Your circle is waiting to be built. Meet someone from the scene.</div>'}</section><section class="card"><div class="card-head"><div><div class="card-kicker">INDUSTRY PULSE</div><h2 class="card-title">News from the scene</h2></div></div>${feed(state.news,6)}</section></section></div>`}
function artistRows(arr){return arr.map(a=>`<div class="list-row"><div class="cover">${a.real?'★':'♪'}</div><div class="row-main"><div class="row-title">${esc(a.stage)} ${a.real?'<span class="tiny">ICON</span>':''}</div><div class="row-sub">${esc(a.genre)} · age ${a.age} · ${Math.round(a.pop)} pop</div></div><button class="btn small" data-artist="${a.id}">Connect</button></div>`).join('')}
function businessPage(){return `<h1 class="page-title">Own the room.</h1><p class="page-subtitle">Be your own boss, build a roster, and turn great music into a lasting business.</p><div class="section-grid"><section class="card"><div class="card-head"><div><div class="card-kicker">YOUR IMPRINT</div><h2 class="card-title">${state.label?esc(state.label.name):'Start a record label'}</h2></div>${state.label?'<span class="badge">ACTIVE</span>':''}</div>${state.label?`<p class="tiny">${esc(state.label.motto||'Independent by design.')} · ${state.label.artists.length} signed artist${state.label.artists.length===1?'':'s'} · ${money(state.label.balance)} label balance</p><div class="wealth-row"><span>Label revenue</span><span>${money(state.label.revenue)}</span></div><div class="wealth-row"><span>Artist roster</span><span>${state.label.artists.length}</span></div><div class="choice-list" style="margin-top:13px"><button class="choice" data-action="sign-artist"><b>＋ Sign an artist</b><span>Offer a developing artist a deal. They have their own career and catalog.</span></button><button class="choice" data-action="label-invest"><b>↗ Fund a label release</b><span>Invest in your roster to accelerate an artist's next release.</span></button></div>`:`<p class="tiny">Found an independent label and develop artists on your terms. Establishing an imprint costs $5,000.</p><button class="btn primary" data-action="start-label" style="margin-top:10px">＋ Found a record label · $5,000</button>`}</section><section class="card"><div class="card-head"><div><div class="card-kicker">YOUR BUSINESSES</div><h2 class="card-title">Build beyond the stage</h2></div></div><div class="wealth-row"><span>Investment portfolio</span><span>${money(state.investments)}</span></div><div class="wealth-row"><span>Music royalty catalog</span><span>${money(state.royalties)}</span></div><div class="wealth-row"><span>Properties</span><span>${state.properties.length}</span></div><div class="wealth-row"><span>Vehicles</span><span>${state.garage.length}</span></div><button class="btn small" data-nav="lifestyle" style="margin-top:12px">Explore investments ↗</button></section></div><section class="card"><div class="card-head"><div><div class="card-kicker">PEOPLE MAKE THE MUSIC</div><h2 class="card-title">Your roster</h2></div><button class="btn small" data-nav="industry">Talent search ↗</button></div>${state.label?.artists.length?state.label.artists.map(aid=>{let a=state.artists.find(x=>x.id===aid);return a?`<div class="list-row"><div class="cover">♪</div><div class="row-main"><div class="row-title">${esc(a.stage)}</div><div class="row-sub">${esc(a.genre)} · ${Math.round(a.pop)} popularity · ${compact(a.releases?.length||0)} releases</div></div><button class="btn small" data-action="label-release" data-id="${a.id}">Fund release</button></div>`:''}).join(''):'<div class="empty">An empty roster is full of potential. Meet artists and offer them a deal.</div>'}</section><section class="card"><div class="card-head"><div><div class="card-kicker">YOUR CONTRACTS</div><h2 class="card-title">Deal history</h2></div></div>${state.contracts.length?state.contracts.map(c=>`<div class="list-row"><div class="cover">▣</div><div class="row-main"><div class="row-title">${esc(c.name)} · ${esc(c.type)}</div><div class="row-sub">${c.years} year deal · ${c.royalty}% artist royalty · ${c.control?'creative control':'label-led'}</div></div><span class="badge gray">${esc(c.status)}</span></div>`).join(''):'<div class="empty">No deals signed. Stay independent or build your own terms.</div>'}</section>`}
const closet=[['Shirt','Soul revue shirt',280,'Vintage'],['Jacket','Velvet stage jacket',950,'Vintage'],['Trousers','Wide-leg flares',420,'Vintage'],['Shoes','Platform boots',380,'Vintage'],['Hat','Wide brim hat',190,'Vintage'],['Coat','Touring greatcoat',1250,'Vintage'],['Outfit','Indie tour set',780,'Streetwear'],['Jacket','Streetwear varsity',680,'Streetwear'],['Outfit','Designer runway look',5500,'Luxury'],['Shoes','Custom leather sneakers',850,'Streetwear'],['Hat','Tour bucket hat',130,'Streetwear'],['Jacket','Archive leather',2400,'Luxury']];
const jewels=[['Chain','Gold rope chain',850],['Necklace','Diamond pendant',4200],['Ring','Signet ring',720],['Watch','Heritage chronograph',6800],['Bracelet','Gold cuff',1100],['Earrings','Diamond studs',1650],['Accessory','Vintage shades',290],['Watch','Tourbillon timepiece',32000]];
const cars=[['1970 Chevrolet Chevelle',1970,38000,'Classic'],['1985 Mercedes-Benz 560 SL',1985,46000,'Luxury'],['1992 Acura NSX',1991,88000,'Sports'],['2005 Porsche 911',2005,96000,'Sports'],['2012 Range Rover',2012,72000,'SUV'],['2018 Lamborghini Urus',2018,220000,'Luxury SUV'],['2024 Lucid Air Sapphire',2024,250000,'Electric'],['2026 Rimac Nevera',2026,2100000,'Supercar']];
const properties=[['City apartment',0,160000,850],['Family home',0,390000,1700],['Recording studio loft',0,750000,2800],['Hillside estate',0,2400000,6500],['Commercial rehearsal space',0,1200000,5800],['Coastal compound',0,6200000,15000]];
function clothingPage(){let tabs=[['clothes','Clothing'],['jewelry','Jewelry & accessories'],['tattoos','Tattoos'],['wardrobe','Wardrobe']];let content='';if(styleTab==='clothes')content=`<div class="section-grid"><section class="card"><div class="card-head"><div><div class="card-kicker">THE EDIT</div><h2 class="card-title">Clothing store</h2></div><span class="badge gray">ALL ERAS</span></div><p class="tiny">Shopping blends historical pieces with modern looks. Nothing is era-locked.</p>${closet.map((x,i)=>`<div class="list-row"><div class="cover">◇</div><div class="row-main"><div class="row-title">${esc(x[1])}</div><div class="row-sub">${esc(x[0])} · ${esc(x[3])}${state.character.wardrobe.includes(x[1])?' · OWNED':''}</div></div><div class="row-value">${money(x[2])}</div><button class="btn small" data-buy="cloth:${i}" ${state.character.wardrobe.includes(x[1])?'disabled':''}>${state.character.wardrobe.includes(x[1])?'Owned':'Buy'}</button></div>`).join('')}</section><section class="card"><div class="card-head"><div><div class="card-kicker">MAKE IT YOURS</div><h2 class="card-title">Outfit builder</h2></div></div><div class="field"><label>Current aesthetic</label><select id="style-select">${['Vintage Soul','Streetwear','Luxury','Rock & Roll','Minimal','Avant-Garde','Custom'].map(s=>`<option ${state.character.style===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>Portrait</label><div class="portrait-picker">${['🎙️','🎤','🎸','🎹','🎧','🕶️','✨','👑'].map(a=>`<button class="portrait-option ${state.character.avatar===a?'selected':''}" data-avatar="${a}">${a}</button>`).join('')}</div></div><button class="btn primary" data-action="save-style">Save look</button><div class="notice">Current era: ${esc(era(state.year).tag)}. Your style is never restricted by the timeline.</div></section></div>`;else if(styleTab==='jewelry')content=`<section class="card"><div class="card-head"><div><div class="card-kicker">PERSONAL COLLECTION</div><h2 class="card-title">Jewelry & accessories</h2></div><span class="badge gray">${state.character.jewelry.length} OWNED</span></div><p class="tiny">Signature pieces for every era. Purchases are saved to your collection.</p>${jewels.map((x,i)=>`<div class="list-row"><div class="cover">✧</div><div class="row-main"><div class="row-title">${esc(x[1])}</div><div class="row-sub">${esc(x[0])}${state.character.jewelry.includes(x[1])?' · OWNED':''}</div></div><div class="row-value">${money(x[2])}</div><button class="btn small" data-buy="jewel:${i}">Buy</button></div>`).join('')}<div class="notice">Your collection: ${state.character.jewelry.length?state.character.jewelry.map(esc).join(' · '):'No accessories yet.'}</div></section>`;else if(styleTab==='tattoos')content=`<section class="card"><div class="card-head"><div><div class="card-kicker">INK</div><h2 class="card-title">Tattoo studio</h2></div><span class="badge gray">${state.character.tattoos?.length||0} TATTOOS</span></div><p class="tiny">Choose artwork and placement. Your tattoos stay with you.</p><div class="quick-grid" style="margin-top:13px">${[['Lyric script','Arm'],['Rose & thorns','Shoulder'],['Soundwave','Wrist'],['Legacy portrait','Chest']].map((t,i)=>`<button class="quick-card" data-tattoo="${i}"><span class="quick-icon">✺</span><b>${t[0]}</b><span>${t[1]} · ${money(350+i*250)}</span></button>`).join('')}</div><div class="wealth-row"><span>Your tattoos</span><span>${state.character.tattoos?.length||0}</span></div>${state.character.tattoos?.length?state.character.tattoos.map((t,i)=>`<div class="list-row"><div class="cover">✺</div><div class="row-main"><div class="row-title">${esc(t.design)}</div><div class="row-sub">${esc(t.place)}</div></div><button class="btn small" data-remove-tattoo="${i}">Remove</button></div>`).join(''):'<div class="empty">No tattoos yet. Your story is still unwritten.</div>'}</section>`;else content=`<section class="card"><div class="card-head"><div><div class="card-kicker">YOUR LOOKS</div><h2 class="card-title">Wardrobe</h2></div><button class="btn small primary" data-action="save-outfit">Save current outfit</button></div><p class="tiny">Your collection and saved looks travel with your career.</p><div class="wealth-row"><span>Current aesthetic</span><b>${esc(state.character.style)}</b></div><div class="wealth-row"><span>Owned clothing pieces</span><b>${state.character.wardrobe.length}</b></div><div class="list-row"><div class="cover">◇</div><div class="row-main"><div class="row-title">Everyday Look</div><div class="row-sub">Your original wardrobe staple</div></div></div>${state.character.wardrobe.filter(x=>x!=='Everyday Look').map(x=>`<div class="list-row"><div class="cover">◇</div><div class="row-main"><div class="row-title">${esc(x)}</div><div class="row-sub">Owned clothing</div></div></div>`).join('')}<div class="card-head" style="margin-top:18px"><div><div class="card-kicker">SAVED OUTFITS</div><h2 class="card-title">Looks to remember</h2></div></div>${state.character.outfits?.length?state.character.outfits.map(x=>`<div class="list-row"><div class="cover">✦</div><div class="row-main"><div class="row-title">${esc(x)}</div></div></div>`).join(''):'<div class="empty">Save a look to start your outfit book.</div>'}<div class="notice">Jewelry collection: ${state.character.jewelry.length?state.character.jewelry.map(esc).join(' · '):'No accessories yet.'}</div></section>`;return `<h1 class="page-title">Wear your story.</h1><p class="page-subtitle">Your aesthetic, your rules. Shop across eras, mix it up, and build a wardrobe that stays yours forever.</p><div class="tabs">${tabs.map(([key,label])=>`<button class="tab ${styleTab===key?'active':''}" data-tab="${key}">${label}</button>`).join('')}</div>${content}`}
function lifestylePage(){return `<h1 class="page-title">The life around the music.</h1><p class="page-subtitle">Build a home, enjoy the things you earn, and keep an eye on the balance sheet.</p><div class="section-grid"><section class="card"><div class="card-head"><div><div class="card-kicker">REAL ESTATE</div><h2 class="card-title">Find a place to land</h2></div></div>${properties.map((p,i)=>`<div class="list-row"><div class="cover">⌂</div><div class="row-main"><div class="row-title">${esc(p[0])}</div><div class="row-sub">${money(p[3])}/week upkeep</div></div><div class="row-value">${money(p[2])}</div><button class="btn small" data-buy="property:${i}">Buy</button></div>`).join('')}${state.properties.length?`<div class="notice">Owned: ${state.properties.map(p=>esc(p.name)).join(' · ')}</div>`:''}</section><section class="card"><div class="card-head"><div><div class="card-kicker">GARAGE</div><h2 class="card-title">Take the scenic route</h2></div></div>${cars.map((c,i)=>`<div class="list-row"><div class="cover">▰</div><div class="row-main"><div class="row-title">${esc(c[0])}</div><div class="row-sub">${esc(c[3])} · ${c[1]}</div></div><div class="row-value">${money(c[2])}</div><button class="btn small" data-buy="car:${i}">Buy</button></div>`).join('')}${state.garage.length?`<div class="notice">Your garage: ${state.garage.map(c=>esc(c.name)).join(' · ')}</div>`:''}</section></div><div class="section-grid"><section class="card"><div class="card-head"><div><div class="card-kicker">MONEY MOVES</div><h2 class="card-title">Invest in your future</h2></div></div><p class="tiny">Put cash to work. Investments can rise or fall with each passing week.</p><div class="wealth-row"><span>Portfolio value</span><b>${money(state.investments)}</b></div><button class="btn primary" data-action="invest">Invest $5,000</button><button class="btn" data-action="withdraw">Withdraw $5,000</button></section><section class="card"><div class="card-head"><div><div class="card-kicker">YOUR BALANCE SHEET</div><h2 class="card-title">A life in numbers</h2></div></div><div class="wealth-row"><span>Available cash</span><b>${money(state.cash)}</b></div><div class="wealth-row"><span>Property & vehicles</span><b>${money(state.properties.reduce((a,x)=>a+x.value,0)+state.garage.reduce((a,x)=>a+x.value,0))}</b></div><div class="wealth-row"><span>Royalties earned</span><b>${money(state.royalties)}</b></div><div class="wealth-row"><span>Estimated net worth</span><b>${money(netWorth())}</b></div></section></div>`}
function characterPage(){return `<h1 class="page-title">The person behind the music.</h1><p class="page-subtitle">Your roots, your name and the details that make the artist unmistakably yours.</p><div class="section-grid"><section class="card"><div class="card-head"><div><div class="card-kicker">YOUR STORY</div><h2 class="card-title">Career profile</h2></div></div><div class="hero-content"><div class="avatar">${esc(state.character.avatar)}</div><div><div class="artist-handle">${esc(state.character.stage)}</div><h2>${esc(state.character.first)} ${esc(state.character.last)}</h2><span class="tag">${age()} YEARS · ${esc(state.character.location)}</span></div></div><div class="wealth-row"><span>Born</span><b>${esc(state.character.birth)}</b></div><div class="wealth-row"><span>Career started</span><b>${state.year}</b></div><div class="wealth-row"><span>Weeks in the game</span><b>${state.stats.weeks}</b></div><div class="wealth-row"><span>Shows played</span><b>${state.stats.shows}</b></div><div class="wealth-row"><span>Collaborations</span><b>${state.stats.collaborations}</b></div><button class="btn" data-action="edit-profile">Edit profile</button></section><section class="card"><div class="card-head"><div><div class="card-kicker">YOUR LEGACY</div><h2 class="card-title">Milestones</h2></div></div>${milestoneRows()}<div class="wealth-row"><span>Releases</span><b>${state.releases.length}</b></div><div class="wealth-row"><span>Lifetime streams</span><b>${compact(state.totalStreams)}</b></div><div class="wealth-row"><span>Career status</span><b>${esc(state.careerStatus)}</b></div><button class="btn" data-action="home">Save & exit to careers</button></section></div><section class="card"><div class="card-head"><div><div class="card-kicker">YOUR JOURNAL</div><h2 class="card-title">Recent weeks</h2></div></div>${feed(state.activities,8)}</section>`}
function renderModal(){if(!modal)return '';return `<div class="modal-backdrop" data-dismiss="1"><section class="modal" role="dialog" aria-modal="true"><button class="modal-close" data-action="close-modal">×</button>${modal}</section></div>`}
function showModal(html){modal=html;render()}
function careerForm(){return `<div class="card-kicker">A NEW CHAPTER</div><h2 class="card-title">Create your artist</h2><form id="career-form"><div class="field"><label>First name</label><input name="first" required maxlength="24" placeholder="Jade"></div><div class="field"><label>Last name</label><input name="last" required maxlength="24" placeholder="Stone"></div><div class="field"><label>Stage name (optional)</label><input name="stage" maxlength="32" placeholder="Your name in lights"></div><div class="field"><label>Starting year</label><input name="year" type="number" min="1970" max="2039" value="${new Date().getFullYear()}"></div><div class="field"><label>Birth date</label><input name="birth" type="date" value="${new Date().getFullYear()-18}-06-15"></div><div class="field"><label>Hometown</label><input name="location" maxlength="48" value="Detroit, Michigan"></div><div class="modal-buttons"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary">Start my career</button></div></form>`}
function profileForm(){return `<div class="card-kicker">MAKE IT OFFICIAL</div><h2 class="card-title">Edit profile</h2><form id="profile-form"><div class="field"><label>Stage name</label><input name="stage" maxlength="32" value="${esc(state.character.stage)}" required></div><div class="field"><label>Hometown</label><input name="location" maxlength="48" value="${esc(state.character.location)}" required></div><div class="field"><label>Birth date</label><input name="birth" type="date" value="${esc(state.character.birth)}" required></div><div class="modal-buttons"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary">Save changes</button></div></form>`}
function freshSlot(){for(let i=1;i<=5;i++)if(!saves[`career-${i}`])return `career-${i}`;return null}
function spend(amount){if(state.cash<amount){notify('Not enough cash for that move.');return false}state.cash-=amount;return true}
function log(text,icon='♪'){state.activities.unshift({icon,text,when:fmtDate()});state.activities=state.activities.slice(0,30)}
function release(kind){const costs={Single:10,EP:25,Album:40},cost=costs[kind]||10;if(state.ep<cost){notify(`You need ${cost} EP to make a ${kind.toLowerCase()}.`);return}state.ep-=cost;let title=pick(names),genre=pick(era(state.year).genres),quality=clamp(24+state.popularity*.28+state.heat*.18+Math.random()*34,8,96);let track=makeTrack({id:'player',stage:state.character.stage},title,genre,quality,kind,state.year);track.player=true;track.promo=0;track.streams=0;track.score=quality*(kind==='Album'?1.5:kind==='EP'?1.2:1);state.tracks.push(track);state.releases.push(track);state.popularity=clamp(state.popularity+2,0,100);state.heat=clamp(state.heat+4,0,100);log(`${kind} “${title}” is out in the world. The first reviews are coming in.`,'♫');notify(`${kind} released: ${title}`);save();render()}
function weekly(){state.week++;if(state.week>52){state.week=1;state.year++;state.artists.push(makeArtist(state.year));state.artists=state.artists.filter(a=>!a.real||state.year<=famous.find(f=>`real-${f[0].replace(/\W/g,'')}`===a.id)?.[3]);state.ep=100;state.heat=clamp(state.heat-3,0,100)}else state.ep=Math.min(100,state.ep+28);state.stats.weeks++;let earned=0;state.tracks.forEach(t=>{let base=Math.max(150,Math.round((t.score*850+state.popularity*100+state.heat*50)*(0.75+Math.random()*.5)));t.streams+=base;t.weeks++;if(t.player)earned+=Math.max(1,Math.round(base*(state.year<2000?.0008:.0025)));t.cert=t.streams>=10000000?'Diamond':t.streams>=5000000?'Platinum':t.streams>=1000000?'Gold':t.cert||''});state.totalStreams=state.tracks.filter(t=>t.player).reduce((s,t)=>s+t.streams,0);state.royalties+=earned;state.cash+=earned;state.tracks.filter(t=>t.player).forEach(t=>{let sales=Math.round(t.score*2);t.sales+=sales;state.totalSales+=sales});state.heat=clamp(state.heat+(state.releases.length?1:-1)+Math.random()*4-2,0,100);state.popularity=clamp(state.popularity+(state.releases.length?.2:0)+Math.random()*1.5-.5,0,100);state.properties.forEach(p=>state.cash-=p.upkeep||0);if(state.investments)state.investments=Math.max(0,Math.round(state.investments*(.985+Math.random()*.035)));if(state.label){let revenue=state.label.artists.length*Math.round(120+Math.random()*300);state.label.balance+=revenue;state.label.revenue+=revenue;state.cash+=revenue}let charts=state.tracks.slice().sort((a,b)=>(b.score+Math.log10(b.streams+1)*2)-(a.score+Math.log10(a.streams+1)*2));state.chart.hot=charts.slice(0,30).map((t,i)=>({...t,peak:t.peak?Math.min(t.peak,i+1):i+1}));state.chart.albums=charts.filter(t=>t.kind!=='Single').slice(0,30);let top=state.chart.hot.findIndex(t=>t.player);if(top>=0&&top<10){state.heat=clamp(state.heat+2,0,100);if(top===0)state.stats.numberOnes++}state.lastReport={streams:state.totalStreams,earned,chart:top<0?'—':`#${top+1}`,date:fmtDate()};let headline=pick([`${state.character.stage} keeps building momentum.`,`The scene is buzzing about ${pick(names)}.`,`A new sound is taking over the airwaves.`]);state.news.unshift({icon:'✦',text:headline,when:fmtDate()});state.news=state.news.slice(0,20);log(`Week closed: ${compact(earned)} in royalties, ${compact(state.totalStreams)} lifetime streams.`,'◷');save();render();notify(`Week ${state.week}: ${money(earned)} earned in royalties.`)}
function action(name,el){if(name==='new-career'){if(Object.keys(saves).length>=5){notify('All five career slots are full.');return}showModal(careerForm())}else if(name==='next-week')weekly();else if(name==='close-modal'){modal=null;render()}else if(name==='perform'){if(state.ep<15){notify('You need 15 EP to play a show.');return}state.ep-=15;state.stats.shows++;let earned=Math.round(150+state.popularity*70+Math.random()*300);state.cash+=earned;state.heat=clamp(state.heat+5,0,100);state.popularity=clamp(state.popularity+1.5,0,100);log(`Played a show and brought home ${money(earned)}.`,'♫');save();render();notify(`Great show. You earned ${money(earned)}.`)}else if(name==='create-release')release(el.dataset.kind);else if(name==='show-more-artists'){$('#artist-list').innerHTML=artistRows(state.artists.slice().sort((a,b)=>b.pop-a.pop));el.remove()}else if(name==='save-style'){state.character.style=$('#style-select')?.value||state.character.style;save();render();notify('Look saved.')}else if(name==='save-outfit'){let outfit=`${state.character.style} · ${state.character.wardrobe.slice(-2).join(' + ')||'Everyday Look'}`;state.character.outfits.push(outfit);save();render();notify('Outfit saved to your wardrobe.')}else if(name==='start-label'){if(!spend(5000))return;state.label={name:`${state.character.stage} Records`,motto:'Independent by design.',artists:[],balance:0,revenue:0};state.careerStatus='Label founder';log(`Founded ${state.label.name}.`,'▣');save();render();notify('Your label is open for business.')}else if(name==='sign-artist'){if(!state.label){notify('Found your label first.');return}let candidates=state.artists.filter(a=>!a.real&&!state.label.artists.includes(a.id));if(!candidates.length){notify('No unsigned artists are available right now.');return}let a=pick(candidates),fee=Math.round(1000+a.pop*100);if(!spend(fee))return;state.label.artists.push(a.id);state.label.balance-=fee;log(`${a.stage} signed with ${state.label.name} for ${money(fee)}.`,'◎');save();render();notify(`${a.stage} joined your roster.`)}else if(name==='label-invest'){if(!state.label||!state.label.artists.length){notify('Sign an artist before funding a release.');return}if(!spend(2500))return;state.label.balance-=2500;state.label.revenue+=Math.round(2500+Math.random()*4000);state.label.balance+=Math.round(2500+Math.random()*4000);log('Your label funded a release for its roster.','▣');save();render();notify('The label release campaign is underway.')}else if(name==='invest'){if(spend(5000)){state.investments+=5000;save();render();notify('Investment added to your portfolio.')}}else if(name==='withdraw'){if(state.investments<5000){notify('Your portfolio needs at least $5,000 to withdraw.');return}state.investments-=5000;state.cash+=5000;save();render()}else if(name==='form-group'){showModal(`<div class="card-kicker">MAKE SOMETHING TOGETHER</div><h2 class="card-title">Form a group</h2><form id="group-form"><div class="field"><label>Group name</label><input name="name" required maxlength="32" placeholder="The name on the marquee"></div><div class="field"><label>Choose a collaborator</label><select name="artist">${state.artists.filter(a=>!a.real).slice(0,20).map(a=>`<option value="${a.id}">${esc(a.stage)} · ${esc(a.genre)}</option>`).join('')}</select></div><div class="modal-buttons"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary">Form the group</button></div></form>`)}else if(name==='edit-profile')showModal(profileForm());else if(name==='home'){save();state=null;activeId=null;page='dashboard';render()}}
function buy(code){let [type,index]=code.split(':'),i=+index,success=false;if(type==='cloth'){let x=closet[i];if(!x)return;if(state.character.wardrobe.includes(x[1])){notify('You already own that piece.');return}if(spend(x[2])){state.character.wardrobe.push(x[1]);success=true}}else if(type==='jewel'){let x=jewels[i];if(!x)return;if(state.character.jewelry.includes(x[1])){notify('You already own this accessory.');return}if(spend(x[2])){state.character.jewelry.push(x[1]);success=true}}else if(type==='car'){let x=cars[i];if(!x)return;if(state.garage.some(c=>c.name===x[0])){notify('You already own this vehicle.');return}if(spend(x[2])){state.garage.push({name:x[0],value:x[2]});success=true}}else if(type==='property'){let x=properties[i];if(!x)return;if(state.properties.some(p=>p.name===x[0])){notify('You already own this property.');return}if(spend(x[2])){state.properties.push({name:x[0],value:x[2],upkeep:x[3]});success=true}}if(!success)return;save();render();notify('Purchase complete.')}
function connect(aid){let a=state.artists.find(x=>x.id===aid);if(!a)return;if(state.relationships[aid]){notify('You already know each other.');return}if(state.ep<8){notify('You need 8 EP to make an introduction.');return}state.ep-=8;let score=Math.round(30+Math.random()*50);state.relationships[aid]={score,type:score>70?'Friend':'Acquaintance'};a.relations.player=score;log(`Made a connection with ${a.stage}.`,'◎');save();render();notify(`You connected with ${a.stage}.`)}
function formSubmit(form){let d=Object.fromEntries(new FormData(form));if(form.id==='career-form'){let slot=freshSlot();if(!slot){notify('All career slots are full.');return}let year=clamp(+d.year||1978,1970,2039);state=createCareer({...d,year},slot);activeId=slot;state.character.birth=d.birth||`${year-18}-06-15`;page='dashboard';modal=null;save();render();notify('Your career begins now.')}else if(form.id==='profile-form'){state.character.stage=d.stage;state.character.location=d.location;state.character.birth=d.birth;modal=null;save();render();notify('Profile updated.')}else if(form.id==='group-form'){if(!d.name||state.ep<12){notify('Name your group and make sure you have 12 EP.');return}state.ep-=12;state.groups.push({name:d.name,artistId:d.artist,members:[state.character.stage,state.artists.find(a=>a.id===d.artist)?.stage].filter(Boolean)});state.stats.collaborations++;state.popularity=clamp(state.popularity+2,0,100);log(`${d.name} formed with a new creative partner.`,'♫');modal=null;save();render();notify(`${d.name} is official.`)}}
document.addEventListener('click',e=>{let navBtn=e.target.closest('[data-nav]');if(navBtn){if(navBtn.dataset.nav==='home'){state=null;activeId=null;render();return}page=navBtn.dataset.nav;render();return}let act=e.target.closest('[data-action]');if(act){action(act.dataset.action,act);return}let load=e.target.closest('[data-load]');if(load){activeId=load.dataset.load;state=saves[activeId];page='dashboard';render();return}let del=e.target.closest('[data-delete]');if(del){delete saves[del.dataset.delete];localStorage.setItem(KEY,JSON.stringify(saves));render();notify('Career deleted.');return}let b=e.target.closest('[data-buy]');if(b){buy(b.dataset.buy);return}let artist=e.target.closest('[data-artist]');if(artist){connect(artist.dataset.artist);return}let avatar=e.target.closest('[data-avatar]');if(avatar){state.character.avatar=avatar.dataset.avatar;save();render();return}let tattoo=e.target.closest('[data-tattoo]');if(tattoo){let designs=[['Lyric script','Arm'],['Rose & thorns','Shoulder'],['Soundwave','Wrist'],['Legacy portrait','Chest']][+tattoo.dataset.tattoo];let cost=350+(+tattoo.dataset.tattoo)*250;if(spend(cost)){state.character.tattoos.push({design:designs[0],place:designs[1]});save();render();notify('The ink is yours.')}return}let remove=e.target.closest('[data-remove-tattoo]');if(remove){state.character.tattoos.splice(+remove.dataset.removeTattoo,1);save();render();return}if(e.target.matches('[data-dismiss]')){modal=null;render()}});
document.addEventListener('submit',e=>{if(e.target.matches('#career-form,#profile-form,#group-form')){e.preventDefault();formSubmit(e.target)}});
document.addEventListener('change',e=>{if(e.target.id==='artist-search'){let q=e.target.value.toLowerCase();$('#artist-list').innerHTML=artistRows(state.artists.filter(a=>(a.stage+' '+a.genre).toLowerCase().includes(q)).slice(0,30))}});
document.addEventListener('click',e=>{let tab=e.target.closest('[data-tab]');if(!tab)return;if($('#chart-view')){let key=tab.dataset.tab,list=key==='albums'?state.chart.albums:state.chart.hot,view=$('#chart-view');if(key==='artists')view.innerHTML=state.artists.slice().sort((a,b)=>b.pop-a.pop).slice(0,30).map((a,i)=>`<div class="list-row"><div class="rank">${i+1}</div><div class="row-main"><b>${esc(a.stage)}</b><div class="row-sub">${esc(a.genre)} · ${Math.round(a.pop)} popularity</div></div></div>`).join('');else if(key==='genre')view.innerHTML=chartTable(state.chart.hot.slice().sort((a,b)=>b.score-a.score),'GENRE CHARTS');else view.innerHTML=chartTable(list,key==='albums'?'BILLBOARD 200':'HOT 100');tab.parentElement.querySelectorAll('.tab').forEach(t=>t.classList.remove('active'));tab.classList.add('active');return}if(page==='clothing'){styleTab=tab.dataset.tab;render()}});
window.addEventListener('beforeunload',save);render();
})();
